// AlertPanel.js — Right-column panel showing all security alerts

const ICON_MAP = {
  'No Plate':           '🚗',
  'Plate Obscured':     '🚙',
  'Suspicious Vehicle': '⚠️',
  'Wrong Lane':         '🏍️',
};

const SEVERITY_MAP = {
  red:    { stripe: 'alert-stripe-red',    type: 'text-red',    pill: 'pill-red',    label: 'KRITIS'    },
  orange: { stripe: 'alert-stripe-orange', type: 'text-orange', pill: 'pill-orange', label: 'WASPADA'   },
  green:  { stripe: 'alert-stripe-green',  type: 'text-green',  pill: 'pill-accent', label: 'NORMAL'    },
};

const STATUS_PILL = {
  unreviewed: { cls: 'pill-red',    label: 'Unreviewed' },
  reviewing:  { cls: 'pill-orange', label: 'Reviewing'  },
  cleared:    { cls: 'pill-accent', label: 'Cleared'    },
};

function AlertItem({ alert }) {
  const sev    = SEVERITY_MAP[alert.severity] || SEVERITY_MAP.orange;
  const status = STATUS_PILL[alert.status]    || STATUS_PILL.unreviewed;
  const icon   = ICON_MAP[alert.type] || '🚗';

  return (
    <div
      className={`alert-item ${alert.isNew ? 'is-new' : ''} ${alert.severity === 'orange' ? 'type-orange' : ''}`}
    >
      {/* Left severity stripe */}
      <div className={`alert-stripe ${sev.stripe}`}/>

      {/* Vehicle icon thumb */}
      <div className="alert-icon">{icon}</div>

      {/* Content */}
      <div className="alert-body">
        <div className={`alert-type ${sev.type}`}>{alert.type}</div>
        <div className="alert-desc">{alert.description}</div>
        <div className="alert-meta">
          <span className="alert-time">{alert.time} · {alert.camera}</span>
          <span className={`status-pill ${status.cls}`} style={{ fontSize: 7, padding: '2px 7px' }}>
            {status.label}
          </span>
        </div>
      </div>
    </div>
  );
}

export default function AlertPanel({ alerts }) {
  const unreviewed = alerts.filter(a => a.status === 'unreviewed').length;
  const newCount   = alerts.filter(a => a.isNew).length;

  return (
    <div className="card" style={{ display: 'flex', flexDirection: 'column', maxHeight: 'calc(100vh - 110px)' }}>
      <div className="card-header">
        <span className="card-title">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
            <line x1="12" y1="9"  x2="12" y2="13"/>
            <line x1="12" y1="17" x2="12.01" y2="17"/>
          </svg>
          Security Alerts
        </span>

        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {newCount > 0 && (
            <div className="animate-slide-top" style={{
              background: 'var(--red)',
              color: '#fff',
              borderRadius: 20,
              padding: '2px 8px',
              fontFamily: 'var(--font-display)',
              fontSize: 7.5,
              fontWeight: 700,
              letterSpacing: '1.5px',
              boxShadow: '0 0 12px rgba(255,45,85,0.5)',
            }}>
              {newCount} BARU
            </div>
          )}
          {unreviewed > 0 && (
            <span className="status-pill pill-red" style={{ fontSize: 7 }}>
              <span className="dot dot-red dot-pulse"/>
              {unreviewed} PENDING
            </span>
          )}
        </div>
      </div>

      {/* Scrollable list */}
      <div style={{
        flex: 1,
        overflowY: 'auto',
        padding: '12px 12px',
        display: 'flex',
        flexDirection: 'column',
        gap: 8,
        minHeight: 0,
      }}>
        {alerts.length === 0 ? (
          <div style={{
            display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            padding: '48px 20px', gap: 12,
          }}>
            <div style={{ fontSize: 36, opacity: 0.18 }}>🛡️</div>
            <div style={{
              fontFamily: 'var(--font-mono)',
              fontSize: 9.5,
              color: 'var(--text-3)',
              letterSpacing: '2px',
              textAlign: 'center',
              lineHeight: 1.8,
            }}>
              NO ALERTS DETECTED<br/>SYSTEM MONITORING ACTIVE
            </div>
          </div>
        ) : (
          alerts.map(a => <AlertItem key={a.id} alert={a}/>)
        )}
      </div>

      {/* Footer */}
      <div style={{
        borderTop: '1px solid var(--border)',
        padding: '10px 14px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        background: 'rgba(0,0,0,0.2)',
      }}>
        <span style={{
          fontFamily: 'var(--font-mono)',
          fontSize: 8.5,
          color: 'var(--text-3)',
          letterSpacing: '1px',
        }}>
          {alerts.length} TOTAL ALERTS
        </span>

        <button
          className="btn btn-ghost"
          style={{ padding: '4px 10px', fontSize: 8 }}
        >
          Export Log
        </button>
      </div>
    </div>
  );
}
